CREATE TABLE IF NOT EXISTS `wanted_monster_instances` (`instance_id` bigint unsigned NOT NULL AUTO_INCREMENT,`template_id` varchar(64) NOT NULL,`npc_object_id` int NOT NULL DEFAULT 0,`npc_id` int NOT NULL,`category` varchar(24) NOT NULL,`zone_id` varchar(32) NOT NULL,`spawn_x` int NOT NULL,`spawn_y` int NOT NULL,`spawn_z` int NOT NULL,`state` enum('SCHEDULED','ACTIVE','DEFEATED','ESCAPED','CANCELLED','ERROR') NOT NULL,`spawned_at` timestamp NULL,`expires_at` timestamp NULL,`killed_at` timestamp NULL,`killed_by_character_id` int NOT NULL DEFAULT 0,`total_damage` bigint unsigned NOT NULL DEFAULT 0,`failure_reason` varchar(128) NOT NULL DEFAULT '',`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (`instance_id`),KEY `state_expires` (`state`,`expires_at`),KEY `template_created` (`template_id`,`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
CREATE TABLE IF NOT EXISTS `wanted_monster_contributions` (`instance_id` bigint unsigned NOT NULL,`account_name` varchar(45) NOT NULL,`character_id` int NOT NULL,`damage` bigint unsigned NOT NULL DEFAULT 0,`percentage` decimal(8,4) NOT NULL DEFAULT 0,`tier` varchar(16) NOT NULL DEFAULT '',`eligible` tinyint(1) NOT NULL DEFAULT 0,`reward_status` varchar(16) NOT NULL DEFAULT 'NONE',`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (`instance_id`,`account_name`),KEY `account_updated` (`account_name`,`updated_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
CREATE TABLE IF NOT EXISTS `wanted_monster_pending_rewards` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`instance_id` bigint unsigned NOT NULL,`template_id` varchar(64) NOT NULL,`account_name` varchar(45) NOT NULL,`character_id` int NOT NULL,`tier` varchar(16) NOT NULL,`contribution` bigint unsigned NOT NULL,`wanted_seals` int unsigned NOT NULL,`item_rewards` varchar(512) NOT NULL DEFAULT '',`status` enum('PENDING','DELIVERED','CANCELLED') NOT NULL DEFAULT 'PENDING',`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`delivered_at` timestamp NULL,PRIMARY KEY (`id`),UNIQUE KEY `instance_account` (`instance_id`,`account_name`),KEY `account_status` (`account_name`,`status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
CREATE TABLE IF NOT EXISTS `wanted_monster_reward_history` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`instance_id` bigint unsigned NOT NULL,`template_id` varchar(64) NOT NULL,`account_name` varchar(45) NOT NULL,`character_id` int NOT NULL,`contribution` bigint unsigned NOT NULL,`tier` varchar(16) NOT NULL,`wanted_seals` int unsigned NOT NULL,`item_rewards` varchar(512) NOT NULL DEFAULT '',`status` varchar(24) NOT NULL,`failure_reason` varchar(128) NOT NULL DEFAULT '',`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE KEY `instance_account_status` (`instance_id`,`account_name`,`status`),KEY `account_created` (`account_name`,`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
